package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) public class Ui1503Test {
 @Test public void terminalHasOnlyChatReturnAndRemovesOnceAfterTransition(){TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);int[] n={0};AgentTerminalScreen page=new AgentTerminalScreen(a,"long","/long",()->{});page.setOnDismissListener(()->n[0]++);assertNull(page.findViewWithTag("page-menu"));assertTrue(page.findViewWithTag("agent-terminal-return") instanceof WorkspaceIconButton);page.navigationEnabled(true);page.show();page.dismiss();page.dismiss();Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(1));assertEquals(1,n[0]);assertNull(page.getParent());}
 @Test public void libraryGeometrySetBeforeShow(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AlertDialog d=WorkspaceDialogs.builder(a).setMessage("content").create();WorkspaceDialogs.centerLibrary(d);assertFalse(d.isShowing());assertEquals(Gravity.CENTER,d.getWindow().getAttributes().gravity);assertEquals(R.style.WorkspaceLibraryAnimation,d.getWindow().getAttributes().windowAnimations);d.show();assertEquals(Gravity.CENTER,d.getWindow().getAttributes().gravity);d.cancel();assertFalse(d.isShowing());}
 @Test public void existingSessionSettingsHaveNoLaunchSelectorAndRetainProfile()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);java.lang.reflect.Field tv=TermuxActivity.class.getDeclaredField("mTerminalView");tv.setAccessible(true);tv.set(a,a.findViewById(R.id.terminal_view));WorkspaceController c=new WorkspaceController(a);try{java.lang.reflect.Method edit=WorkspaceController.class.getDeclaredMethod("editSession",WorkspaceStore.Session.class,boolean.class);edit.setAccessible(true);for(boolean agent:new boolean[]{false,true}){WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent?"ubuntu":"termux";p.claudeAgent=agent;p.name="Synthetic";p.directory=agent?"/root/project":"/fixture";String before=p.environment;edit.invoke(c,p,false);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNull(d.getWindow().getDecorView().findViewWithTag("session-launch-environment"));d.cancel();assertEquals(before,p.environment);assertEquals(agent?"/root/project":"/fixture",p.directory);}}finally{c.close();a.finish();}}
}
